    public String[] CreateGridWithExactlyOnePath(int m, int n) {
        String[] grid = new String[m];

        StringBuilder top = new StringBuilder(n);
        StringBuilder other = new StringBuilder(n);

        for (int i = 0; i < n - 1; i++) {
            top.append('.');
            other.append('#');
        }
        top.append('.');
        other.append('.');

        grid[0] = top.toString();
        for (int i = 1; i < m; i++) {
            grid[i] = other.toString();
        }
        return grid;
    }
